class Recuperador:
    def __init__(self, docs, encoder, estrategia="seccion", palabras=60, solapamiento=15, metadatos=False,
                 top_k=3, umbral=None, margen=None, reranker=None, candidatos=20):
        self.encoder, self.metadatos = encoder, metadatos
        self.top_k, self.umbral, self.margen = top_k, umbral, margen
        self.reranker, self.candidatos = reranker, candidatos
        self.fragmentos = fragmentar(docs, estrategia, palabras=palabras, solapamiento=solapamiento)
        self.matriz = self._embeddings([f.para_embedding(metadatos) for f in self.fragmentos])

    def _embeddings(self, textos):
        nombre = getattr(self.encoder, "nombre", None)
        if nombre is None:
            return self.encoder.codificar_pasajes(textos)
        prefijo = getattr(self.encoder, "prefijo_pasaje", "")
        clave = hashlib.sha1(json.dumps([nombre, prefijo, textos]).encode()).hexdigest()[:16]
        ruta = CACHE / f"{clave}.npy"
        if ruta.exists():
            return np.load(ruta)
        m = self.encoder.codificar_pasajes(textos)
        CACHE.mkdir(parents=True, exist_ok=True)
        np.save(ruta, m)
        return m

def _puntuar(self, consulta):
    """[(Fragmento, score)] de todos los fragmentos (o de los candidatos rerankeados), de mayor a menor."""
    q = self.encoder.codificar_consultas([consulta])[0]
    scores = self.matriz @ q
    orden = np.argsort(-scores)
    if self.reranker is None:
        return [(self.fragmentos[i], float(scores[i])) for i in orden]
    cand = orden[:self.candidatos]
    pares = [(consulta, self.fragmentos[i].para_embedding(self.metadatos)) for i in cand]
    re_scores = self.reranker.predict(pares, show_progress_bar=False)
    return sorted(((self.fragmentos[i], float(s)) for i, s in zip(cand, re_scores)), key=lambda x: -x[1])

def puntuar(self, consulta):
    """[(texto, score)] de mayor a menor."""
    return [(f.texto, s) for f, s in self._puntuar(consulta)]

def buscar_fragmentos(self, consulta, **seleccion):
    """Los Fragmento elegidos (texto literal + documento, título y sección). top_k, umbral y margen se
    pueden pisar por llamada; si no, se usan los de la configuración."""
    s = {"top_k": self.top_k, "umbral": self.umbral, "margen": self.margen, **seleccion}
    return seleccionar(self._puntuar(consulta), s["top_k"], s["umbral"], s["margen"])

def buscar(self, consulta):
    return [f.texto for f in self.buscar_fragmentos(consulta)]

import json

from hospital.rag.recuperador import CONFIG, obtener_recuperador

SEPARADOR = "\n\n---\n\n"


def seleccion_agente():
    return json.loads(CONFIG.read_text(encoding="utf-8")).get("agente", {})


def buscar_documentos(consulta):
    """Fragmentos elegidos, cada uno con su fuente '[Documento > Sección]' arriba del texto literal."""
    seleccion = seleccion_agente()
    # En consultas sobre documentacion o que llevar, la seccion especifica puede
    # quedar tercera cuando la pregunta tambien menciona el tipo de turno.
    # La configuracion de la Parte 1 permanece sin cambios.
    consulta_normalizada = consulta.casefold()
    if "llevar" in consulta_normalizada or "document" in consulta_normalizada:
        seleccion = {**seleccion, "top_k": max(seleccion.get("top_k", 2), 3), "margen": None}
    bloques = []
    for f in obtener_recuperador().buscar_fragmentos(consulta, **seleccion):
        fuente = f"{f.titulo} > {f.seccion}" if f.seccion else f.titulo
        bloques.append(f"[{fuente}]\n{f.texto}")
    return SEPARADOR.join(bloques) or "No se encontraron documentos para esa consulta."

def _tokens(texto: str) -> list[str]:
    normalizado = unicodedata.normalize("NFD", texto.casefold())
    sin_tildes = "".join(c for c in normalizado if unicodedata.category(c) != "Mn")
    return re.findall(r"[a-z0-9]+", sin_tildes)


@dataclass(frozen=True)
class ConfigBM25:
    """Cómo se indexa y cuántas secciones ve el agente.

    prefijo: trunca cada término no numérico a sus primeras letras (stemming por prefijo).
    umbral_relativo: descarta secciones con puntaje menor que esa fracción del primero.
    """

    sin_comunes: bool = False
    prefijo: int | None = None
    umbral_relativo: float = 0.0
    k_entorno: int = 2


VARIANTES = {
    "baseline": ConfigBM25(),
    "sin_comunes": ConfigBM25(sin_comunes=True),
    "prefijos": ConfigBM25(sin_comunes=True, prefijo=4, umbral_relativo=0.6, k_entorno=3),
}

def __init__(self, ruta_normas: Path, variante: str | ConfigBM25 = "baseline"):
    if isinstance(variante, ConfigBM25):
        self.variante, self.config = "personalizada", variante
    elif variante in VARIANTES:
        self.variante, self.config = variante, VARIANTES[variante]
    else:
        raise ValueError(f"BUSCADOR_VARIANTE debe ser una de: {', '.join(VARIANTES)}")
    self.k_entorno = self.config.k_entorno
    self._secciones = cargar_normas(Path(ruta_normas))
    self._frecuencias = [Counter(self._terminos(s.texto)) for s in self._secciones]
    self._longitudes = [sum(f.values()) for f in self._frecuencias]
    self._promedio = sum(self._longitudes) / len(self._longitudes) if self._longitudes else 0
    documentos = Counter(t for f in self._frecuencias for t in f)
    n = len(self._secciones)
    self._idf = {t: math.log(1 + (n - df + 0.5) / (df + 0.5)) for t, df in documentos.items()}

def _terminos(self, texto: str) -> list[str]:
    c = self.config
    terminos = [t for t in _tokens(texto) if not (c.sin_comunes and t in PALABRAS_COMUNES)]
    if c.prefijo:
        terminos = [t if t.isdigit() else t[:c.prefijo] for t in terminos]
    return terminos

def recuperar(self, consulta: str, k: int) -> list[Seccion]:
    """Devuelve hasta k secciones por relevancia BM25 (k1=1.5, b=0.75)."""
    if k <= 0 or not self._promedio:
        return []
    terminos = sorted(set(self._terminos(consulta)))
    puntuados = []
    for i, frecuencias in enumerate(self._frecuencias):
        normalizador = 1.5 * (0.25 + 0.75 * self._longitudes[i] / self._promedio)
        puntaje = sum(
            self._idf[t] * frecuencias[t] * 2.5 / (frecuencias[t] + normalizador)
            for t in terminos if t in frecuencias
        )
        if puntaje > 0:
            puntuados.append((i, puntaje))
    puntuados.sort(key=lambda x: (-x[1], x[0]))
    if puntuados:
        minimo = self.config.umbral_relativo * puntuados[0][1]
        puntuados = [(i, p) for i, p in puntuados if p >= minimo]
    return [self._secciones[i] for i, _ in puntuados[:k]]

class SentenceTransformerEncoder:
    """Modelos entrenados para embeddings de oraciones (MiniLM, e5, bge-m3). Los e5 piden prefijos."""

    def __init__(self, modelo, prefijo_consulta="", prefijo_pasaje="", lote=16):
        from sentence_transformers import SentenceTransformer

        self.nombre, self.lote = modelo, lote
        self.prefijo_consulta, self.prefijo_pasaje = prefijo_consulta, prefijo_pasaje
        self.modelo = SentenceTransformer(modelo, device="cpu")

    def _codificar(self, textos, prefijo):
        m = self.modelo.encode([prefijo + t for t in textos], batch_size=self.lote,
                               normalize_embeddings=True, show_progress_bar=False)
        return np.asarray(m, dtype=np.float32)

    def codificar_consultas(self, textos):
        return self._codificar(textos, self.prefijo_consulta)

    def codificar_pasajes(self, textos):
        return self._codificar(textos, self.prefijo_pasaje)


def crear_encoder(cfg):
    """cfg: {"tipo": "bert_promedio" | "sentence_transformer", "modelo": ..., "prefijo_consulta": ..., "prefijo_pasaje": ...}"""
    if cfg["tipo"] == "bert_promedio":
        return BertPromedio(cfg["modelo"])
    if cfg["tipo"] == "sentence_transformer":
        return SentenceTransformerEncoder(cfg["modelo"], cfg.get("prefijo_consulta", ""), cfg.get("prefijo_pasaje", ""))
    raise ValueError(f"tipo de encoder desconocido: {cfg['tipo']}")

