def _usage(ai):
    u = ai.usage_metadata or {}
    uso = (ai.response_metadata or {}).get("token_usage") or {}
    entrada, salida = u.get("input_tokens", 0), u.get("output_tokens", 0)
    costo = uso.get("cost")
    return {
        "tokens_entrada": entrada,
        "tokens_cache": (u.get("input_token_details") or {}).get("cache_read", 0),
        "tokens_salida": salida,
        "tokens_razonamiento": (u.get("output_token_details") or {}).get("reasoning", 0),
        "costo": costo if costo is not None else entrada * PRECIO_ENTRADA + salida * PRECIO_SALIDA,
        "costo_estimado": costo is None,
        "id": (ai.response_metadata or {}).get("id"),
    }


def resumir(mensajes):
    ais = [m for m in mensajes if isinstance(m, AIMessage)]
    herramientas = []
    for m in ais:
        for c in m.tool_calls:
            if c["name"] not in herramientas:
                herramientas.append(c["name"])
    llamadas = [_usage(m) for m in ais]
    respuesta = next((texto(m.content).strip() for m in reversed(ais) if texto(m.content).strip()), "")
    return {
        "respuesta": respuesta,
        "contextos": [texto(m.content) for m in mensajes if isinstance(m, ToolMessage)],
        "herramientas": herramientas,
        "llamadas_modelo": llamadas,
        "tokens_entrada": sum(l["tokens_entrada"] for l in llamadas),
        "tokens_salida": sum(l["tokens_salida"] for l in llamadas),
        "costo": sum(l["costo"] for l in llamadas),
    }

def _normalizar(m):
    return m / np.linalg.norm(m, axis=1, keepdims=True).clip(min=1e-12)


class BertPromedio:
    """Linea de base obligatoria: BERT sin ajustar para similitud, embedding = promedio de los
    vectores de la ultima capa sobre los tokens reales (se ignora el padding)."""

    def __init__(self, modelo="google-bert/bert-base-multilingual-cased", lote=16):
        from transformers import AutoModel, AutoTokenizer

        self.nombre, self.lote = modelo, lote
        self.tokenizer = AutoTokenizer.from_pretrained(modelo)
        self.modelo = AutoModel.from_pretrained(modelo).eval()

    def _codificar(self, textos):
        import torch

        salidas = []
        with torch.no_grad():
            for i in range(0, len(textos), self.lote):
                enc = self.tokenizer(textos[i:i + self.lote], padding=True, truncation=True,
                                     max_length=512, return_tensors="pt")
                h = self.modelo(**enc).last_hidden_state
                m = enc["attention_mask"].unsqueeze(-1).float()
                salidas.append(((h * m).sum(1) / m.sum(1)).numpy())
        return _normalizar(np.concatenate(salidas))

    codificar_consultas = codificar_pasajes = _codificar

def autoatencion(X, Wq, Wk, Wv, mascara=False):
    """Proyecta X a consultas, claves y valores y aplica atención."""
    X = np.asarray(X)
    Q = X @ np.asarray(Wq)
    K = X @ np.asarray(Wk)
    V = X @ np.asarray(Wv)
    return atencion(Q, K, V, mascara=mascara)


def multicabeza(X, cabezas, Wo, mascara=False):
    """Concatena las salidas de varias cabezas y las proyecta con ``Wo``."""
    salidas = [autoatencion(X, Wq, Wk, Wv, mascara=mascara)[0]
               for Wq, Wk, Wv in cabezas]
    concatenada = np.concatenate(salidas, axis=-1)
    return concatenada @ np.asarray(Wo)
